D="/tmp/probe-lXWK"; su - claude-runner -c "cd '/root/Zheus AI Projects/controle-fabrica' && B=/usr/lib/postgresql/18/bin && \$B/psql -X -h '$D' -p 55441 -U postgres -d postgres -v ON_ERROR_STOP=1 -q <<'EOF' 2>&1 | tail -15
DROP TABLE IF EXISTS t,r,p;
CREATE TABLE financial_transactions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, financial_account_id uuid NOT NULL,
  type text NOT NULL, direction text NOT NULL, company_id uuid, operation_company_id uuid, amount numeric(14,2) NOT NULL,
  occurred_at timestamptz NOT NULL DEFAULT now(), reference_type text, reference_id uuid, payment_method_id uuid,
  financial_category_id uuid, cost_center_id uuid, description text, status text NOT NULL DEFAULT 'POSTED',
  reversal_of_id uuid, idempotency_key text, created_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(organization_id,id), UNIQUE(organization_id,idempotency_key), CHECK(reversal_of_id IS NULL OR reversal_of_id<>id));
CREATE TABLE financial_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, name text, status text DEFAULT 'ACTIVE');
CREATE TABLE companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, legal_name text);
CREATE TABLE account_receivables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, company_id uuid, document_number text NOT NULL, description text);
CREATE TABLE account_payables (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, company_id uuid, document_number text NOT NULL, description text);
