WITH rows AS MATERIALIZED(SELECT t.*,a.name account_name,COALESCE(c.legal_name,'-') company_name,document_number FROM public.financial_transactions t
  JOIN public.financial_accounts a ON a.id=t.financial_account_id AND a.organization_id=:org
  LEFT JOIN public.companies c ON c.id=t.company_id AND c.organization_id=:org
  LEFT JOIN LATERAL (SELECT r.document_number FROM public.account_receivables r WHERE r.id=t.reference_id AND r.organization_id=:org
    UNION ALL SELECT p.document_number FROM public.account_payables p WHERE p.id=t.reference_id AND p.organization_id=:org) d ON true
  WHERE t.organization_id=:org
